// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an address 'from', an address 'callee' (we will deploy a benign helper to receive calls),
    // a uint array length selector n to create arrays of variable length, and a seed to generate values
    function testFuzz_property(address from, uint256 n, uint256 seed) public {
        // keep n reasonable but allow 0..10 (we need non-empty arrays per contract requirement)
        uint256 len = bound(n, 0, 10);
        vm.assume(len > 0); // admissible domain per contract's require

        // deploy a simple callee that accepts low-level calls (always succeeds)
        CalleeReceiver callee = new CalleeReceiver();

        // build arrays according to fuzzed length and seed
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            // derive pseudo-random addresses/values from seed to vary inputs
            // cast hashed value to address
            bytes32 h = keccak256(abi.encodePacked(seed, i, from));
            address addr = address(uint160(uint256(h)));
            tos[i] = addr;
            vals[i] = uint256(keccak256(abi.encodePacked(h, i))) % 100000;
        }

        // Call c.transfer and capture whether it returns (ok) and the returned bool
        bool ok;
        bool ret;
        try c.transfer(from, address(callee), tos, vals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The universal property: for any admissible input (non-empty tos), the reference contract
        // completes and returns true. We assert that the call completed (did not revert) and returned true.
        // This will hold on the reference implementation for all inputs, but the mutant returns false
        // whenever tos.length > 1, causing this assertion to fail for some fuzzed inputs.
        assertTrue(ok && ret);
    }
}

// Minimal benign callee that simply accepts any call and returns; low-level .call will succeed.
contract CalleeReceiver {
    fallback() external payable {
        // no-op, allow call to succeed
    }
    receive() external payable {}
}
